CREATE OR REPLACE FUNCTION public.fn_ca_assert_satellite_asset(p_satellite_id uuid, p_target_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_source boolean; v_target boolean;
BEGIN
  IF p_satellite_id IS NULL OR p_target_id IS NULL THEN
    RAISE EXCEPTION 'a satellite asset check requires the satellite and its target' USING ERRCODE='22004';
  END IF;
  v_source := public.fn_poker_diamond_tournament(p_satellite_id);
  v_target := public.fn_poker_diamond_tournament(p_target_id);
  IF v_source AND NOT v_target THEN
    RAISE EXCEPTION 'diamond_satellite_cannot_seat_a_chip_target: satellite % target %',
      p_satellite_id, p_target_id USING ERRCODE='22023';
  ELSIF v_target AND NOT v_source THEN
    RAISE EXCEPTION 'chip_satellite_cannot_seat_a_diamond_target: satellite % target %',
      p_satellite_id, p_target_id USING ERRCODE='22023';
  END IF;
  RETURN v_source;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_lock_mtt_admission_contract()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
  SELECT abi INTO v_abi FROM public.ca_mtt_admission_contract WHERE singleton FOR SHARE;
  IF NOT FOUND OR v_abi NOT IN ('legacy-capacity-v1','unlimited-mtt-v2') THEN
    RAISE EXCEPTION 'MTT_ADMISSION_CONTRACT_MISSING_OR_UNKNOWN' USING ERRCODE='55000';
  END IF;
  RETURN v_abi;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_tournament_is_unlimited(p_tournament_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v_abi text;
BEGIN
 v_abi:=public.fn_ca_lock_mtt_admission_contract();
 IF v_abi='legacy-capacity-v1' THEN RETURN false; END IF;
 RETURN public.fn_ca_tournament_recorded_format(p_tournament_id) IN ('mtt-v1','mtt-v2');
END $function$
